function Radar({ data, size = 300 }) {
  const pad = 72;
  const box = size + pad * 2;
  const cx = box / 2, cy = box / 2, r = size / 2 - 28, n = Math.max(data.length, 1);
  const ang = i => (Math.PI * 2 * i) / n - Math.PI / 2;
  const pt = (i, v) => [cx + Math.cos(ang(i)) * r * (v / 100), cy + Math.sin(ang(i)) * r * (v / 100)];
  const ring = l => data.map((_, i) => pt(i, l * 100).join(",")).join(" ");
  const poly = data.map((d, i) => pt(i, d.value).join(",")).join(" ");
  const anchorOf = i => {
    const x = Math.cos(ang(i));
    if (x > 0.25) return "start";
    if (x < -0.25) return "end";
    return "middle";
  };
  const baselineOf = i => {
    const y = Math.sin(ang(i));
    if (y > 0.35) return "hanging";
    if (y < -0.35) return "auto";
    return "middle";
  };
  return (
    <svg width="100%" height={box} viewBox={"0 0 " + box + " " + box} role="img" aria-label="スキルレーダーチャート" style={{ maxWidth: box, overflow: "visible" }}>
      {[0.25, 0.5, 0.75, 1].map(l => <polygon key={l} points={ring(l)} fill="none" stroke={T.border} strokeWidth="1" />)}
      {data.map((_, i) => { const [x, y] = pt(i, 100); return <line key={i} x1={cx} y1={cy} x2={x} y2={y} stroke={T.border} strokeWidth="1" />; })}
      <polygon points={poly} fill="rgba(0,160,210,.18)" stroke={T.accent} strokeWidth="2" />
      {data.map((d, i) => { const [x, y] = pt(i, d.value); return <circle key={i} cx={x} cy={y} r="3.5" fill={T.accent} />; })}
      {data.map((d, i) => {
        const lx = cx + Math.cos(ang(i)) * (r + 36), ly = cy + Math.sin(ang(i)) * (r + 36);
        return <text key={i} x={lx} y={ly} fontSize="11" fontWeight="600" fill={T.textSecondary} textAnchor={anchorOf(i)} dominantBaseline={baselineOf(i)}>{d.label}</text>;
      })}
    </svg>
  );
}
function reportUpdatedAt(r) { return r?.updatedAt || r?.submittedAt || r?.createdAt || r?.rawData?.updatedAt || r?.rawData?.submittedAt || r?.rawData?.createdAt || ""; }
function reportSavedLabel(r) {
  if (!r) return "未保存";
  const ts = reportUpdatedAt(r);
  return ts ? "保存済み / 最終更新: " + fmtTs(ts) : "保存済み";
}


